            entity.Property(e => e.SaldoaNegociar)
                .HasComputedColumnSql("(CONVERT([money],case when [segmento_rem]='Pagos No Cast' OR [segmento_rem]='Pri' then case when [mora]='4' then CONVERT([money],[Saldo Deuda])-CONVERT([money],[saldo deuda])*(0.35) when [mora]='5' then CONVERT([money],[Saldo Deuda])-CONVERT([money],[saldo deuda])*(0.40) when [mora]='6' then CONVERT([money],[Saldo Deuda])-CONVERT([money],[saldo deuda])*(0.50)  end  end))", false)
                .HasColumnType("money");
            entity.Property(e => e.SaldoaNegociarCp)
                .HasComputedColumnSql("(CONVERT([money],case when [SEGMENTO]='GOAL' OR [SEGMENTO]='SP2' OR [SEGMENTO]='Special II' OR [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' OR [SEGMENTO]='SEC' OR [SEGMENTO]='SECONDARY' OR [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' OR [SEGMENTO]='FRESH' then case when [SEGMENTO]='FRESH' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.50))+CONVERT([money],[impuestos]) when [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.55))+CONVERT([money],[impuestos]) when [SEGMENTO]='SEC' OR [SEGMENTO]='SECONDARY' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.60))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.65))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special II' OR [SEGMENTO]='SP2' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.70))+CONVERT([money],[impuestos]) when [SEGMENTO]='GOAL' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.80))+CONVERT([money],[impuestos])  end  end))", false)
                .HasColumnType("money")
                .HasColumnName("SaldoaNegociarCP");
            entity.Property(e => e.SaldoaNegociarLp)
                .HasComputedColumnSql("(CONVERT([money],case when [SEGMENTO]='GOAL' OR [SEGMENTO]='SP2' OR [SEGMENTO]='Special II' OR [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' OR [SEGMENTO]='SEC' OR [SEGMENTO]='SECONDARY' OR [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' OR [SEGMENTO]='FRESH' then case when [SEGMENTO]='FRESH' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.40))+CONVERT([money],[impuestos]) when [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.45))+CONVERT([money],[impuestos]) when [SEGMENTO]='SEC' OR [SEGMENTO]='SECONDARY' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.50))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.55))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special II' OR [SEGMENTO]='SP2' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.60))+CONVERT([money],[impuestos]) when [SEGMENTO]='GOAL' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.70))+CONVERT([money],[impuestos])  end  end))", false)
                .HasColumnType("money")
                .HasColumnName("SaldoaNegociarLP");
            entity.Property(e => e.SaldoaNegociarPt)
                .HasComputedColumnSql("(CONVERT([money],case when [SEGMENTO]='GOAL' OR [SEGMENTO]='SP2' OR [SEGMENTO]='Special II' OR [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' OR [SEGMENTO]='SEC' OR [SEGMENTO]='SECONDARY' OR [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' OR [SEGMENTO]='FRESH' then case when [SEGMENTO]='FRESH' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.55))+CONVERT([money],[impuestos]) when [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.60))+CONVERT([money],[impuestos]) when [SEGMENTO]='SEC' OR [SEGMENTO]='SECONDARY' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.65))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.75))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special II' OR [SEGMENTO]='SP2' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.75))+CONVERT([money],[impuestos]) when [SEGMENTO]='GOAL' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.90))+CONVERT([money],[impuestos])  end  end))", false)
                .HasColumnType("money")
                .HasColumnName("SaldoaNegociarPT");
