            entity.Property(e => e.SaldoaNegociar12M)
                .HasComputedColumnSql("(CONVERT([money],[Saldo Deuda])-(CONVERT([money],[Saldo Deuda])*CONVERT([int],replace([Descuento Aplicar 12 Meses],'%','')))/(100))", false)
                .HasColumnType("money");
            entity.Property(e => e.SaldoaNegociar30Días)
                .HasComputedColumnSql("(CONVERT([money],[Saldo Deuda])-(CONVERT([money],[Saldo Deuda])*CONVERT([int],replace([Descuento Aplicar 30 Dias],'%','')))/(100))", false)
                .HasColumnType("money");
            entity.Property(e => e.SaldoaNegociar3M)
                .HasComputedColumnSql("(CONVERT([money],[Saldo Deuda])-(CONVERT([money],[Saldo Deuda])*CONVERT([int],replace([Descuento Aplicar 3 Meses],'%','')))/(100))", false)
                .HasColumnType("money");
            entity.Property(e => e.SaldoaNegociarCp)
                .HasComputedColumnSql("(CONVERT([money],case when [SEGMENTO]='SEC' OR [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' OR [SEGMENTO]='FRESH' OR [SEGMENTO]='Sp2' OR [SEGMENTO]='Sp1' OR [SEGMENTO]='Special II' OR [SEGMENTO]='Special I' OR [SEGMENTO]='Secondary' OR [SEGMENTO]='Goal' then case when [SEGMENTO]='Goal' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.80))+CONVERT([money],[impuestos]) when [SEGMENTO]='SEC' OR [SEGMENTO]='Secondary' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.60))+CONVERT([money],[impuestos]) when [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.55))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.65))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special II' OR [SEGMENTO]='Sp2' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.70))+CONVERT([money],[impuestos]) when [SEGMENTO]='FRESH' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.50))+CONVERT([money],[impuestos])  end  end))", false)
                .HasColumnType("money")
                .HasColumnName("SaldoaNegociarCP");
            entity.Property(e => e.SaldoaNegociarLp)
                .HasComputedColumnSql("(CONVERT([money],case when [SEGMENTO]='SEC' OR [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' OR [SEGMENTO]='FRESH' OR [SEGMENTO]='Sp2' OR [SEGMENTO]='Sp1' OR [SEGMENTO]='Special II' OR [SEGMENTO]='Special I' OR [SEGMENTO]='Secondary' OR [SEGMENTO]='Goal' then case when [SEGMENTO]='Goal' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.70))+CONVERT([money],[impuestos]) when [SEGMENTO]='SEC' OR [SEGMENTO]='Secondary' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.50))+CONVERT([money],[impuestos]) when [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.45))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.55))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special II' OR [SEGMENTO]='Sp2' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.60))+CONVERT([money],[impuestos]) when [SEGMENTO]='FRESH' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.40))+CONVERT([money],[impuestos])  end  end))", false)
                .HasColumnType("money")
                .HasColumnName("SaldoaNegociarLP");
            entity.Property(e => e.SaldoaNegociarPt)
                .HasComputedColumnSql("(CONVERT([money],case when [SEGMENTO]='SEC' OR [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' OR [SEGMENTO]='FRESH' OR [SEGMENTO]='Sp2' OR [SEGMENTO]='Sp1' OR [SEGMENTO]='Special II' OR [SEGMENTO]='Special I' OR [SEGMENTO]='Secondary' OR [SEGMENTO]='Goal' then case when [SEGMENTO]='Goal' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.90))+CONVERT([money],[impuestos]) when [SEGMENTO]='SEC' OR [SEGMENTO]='Secondary' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.65))+CONVERT([money],[impuestos]) when [SEGMENTO]='PRIMARY' OR [SEGMENTO]='PRIM' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.60))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special I' OR [SEGMENTO]='Sp1' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.75))+CONVERT([money],[impuestos]) when [SEGMENTO]='Special II' OR [SEGMENTO]='Sp2' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.75))+CONVERT([money],[impuestos]) when [SEGMENTO]='FRESH' then (CONVERT([money],[saldo capital])-CONVERT([money],[saldo capital])*(0.55))+CONVERT([money],[impuestos])  end  end))", false)
                .HasColumnType("money")
                .HasColumnName("SaldoaNegociarPT");
